draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = '#964B00';
  ctx.fillRect(0, H - 20, W, 20); // floor
  ctx.fillStyle = '#663300';
  ctx.fillRect(10, 10, 100, 20); // bedside table
  ctx.fillStyle = '#663300';
  ctx.fillRect(W - 110, 10, 100, 20); // bedside table
  ctx.fillStyle = '#330033';
  ctx.fillRect(W / 2 - 50, H / 2 - 50, 100, 100); // bed
  ctx.fillStyle = '#330033';
  ctx.fillRect(W / 2 - 20, H / 2 - 20, 40, 40); // pillow
  ctx.fillStyle = '#ffcc00';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 100, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill(); // lamp
  ctx.restore();
}
